import unittest
from app.orders import Line, total_cents


class Contract(unittest.TestCase):
    # planted contradiction: the same input cannot give both totals
    def test_total_a(self):
        self.assertEqual(total_cents([Line('a', 1, 1000)], 10), 990)

    def test_total_b(self):
        self.assertEqual(total_cents([Line('a', 1, 1000)], 10), 1000)
